window.__TNPSC_REGISTER_TEST__("gk", 5, [{"id":401,"subject":"gk","testNumber":5,"question":"இந்திய நிலப்பரப்பின் அட்சப் பரவல் (Latitudinal extent) எவ்வளவு?","options":["8°4' வடக்கு முதல் 37°6' வடக்கு வரை","6°4' வடக்கு முதல் 35°6' வடக்கு வரை","10°4' வடக்கு முதல் 38°6' வடக்கு வரை","8°4' தெற்கு முதல் 37°6' வடக்கு வரை"],"correctAnswer":0,"explanation":"இந்தியாவின் முதன்மை நிலப்பரப்பு 8°4' வடக்கு அட்சம் முதல் 37°6' வடக்கு அட்சம் வரையிலும், 68°7' கிழக்கு தீர்க்கம் முதல் 97°25' கிழக்கு தீர்க்கம் வரையிலும் பரவியுள்ளது. இதனால் இந்தியா முழுமையாக வடகிழக்கு அரைக்கோளத்தில் அமைந்துள்ளது.","difficulty":"easy","topic":"இந்திய அமைவிடம்"},{"id":402,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மிகத் தென்கோடி முனையான 'இந்திரா முனை' (பிக்மெலியன் முனை) எங்கு அமைந்துள்ளது?","options":["கன்னியாகுமரி கடற்கரை","லட்சத்தீவுகளின் மினிக்காய் தீவு","அந்தமான் நிக்கோபார் தீவுக்கூட்டம்","ராமேஸ்வரம் பாம்பன் தீவு"],"correctAnswer":2,"explanation":"இந்தியாவின் தென்கோடி முனையான இந்திரா முனை (முன்பு பிக்மெலியன் முனை) 6°45' வடக்கு அட்சத்தில் அந்தமான் நிக்கோபார் தீவுக்கூட்டத்தின் பெரிய நிக்கோபார் தீவில் அமைந்துள்ளது. இந்திய முதன்மை நிலப்பரப்பின் தென்கோடி முனை குமரி முனை ஆகும்.","difficulty":"easy","topic":"இந்திய அமைவிடம்"},{"id":403,"subject":"gk","testNumber":5,"question":"கடக ரேகை (23°30' வடக்கு) இந்தியாவின் 8 மாநிலங்கள் வழியாகச் செல்கிறது. கீழ்க்கண்டவற்றுள் கடக ரேகை செல்லாத மாநிலம் எது?","options":["குஜராத்","ஒடிசா","ஜார்க்கண்ட்","மிசோரம்"],"correctAnswer":1,"explanation":"கடக ரேகை இந்தியாவின் 8 மாநிலங்கள் வழியாகச் செல்கிறது: குஜராத், ராஜஸ்தான், மத்தியப் பிரதேசம், சத்தீஸ்கர், ஜார்க்கண்ட், மேற்கு வங்காளம், திரிபுரா மற்றும் மிசோரம். ஒடிசா மாநிலம் கடக ரேகைக்குத் தெற்கே அமைந்துள்ளதால் அதன் வழியே செல்லாது.","difficulty":"medium","topic":"இந்திய அமைவிடம்"},{"id":404,"subject":"gk","testNumber":5,"question":"இந்திய திட்ட நேரம் (IST) கணக்கிடப்படும் 82°30' கிழக்கு தீர்க்க ரேகை எந்த நகரத்தின் வழியாகச் செல்கிறது?","options":["நாக்பூர்","போபால்","மிர்சாபூர்","ஜெய்ப்பூர்"],"correctAnswer":2,"explanation":"இந்தியாவின் மத்திய தீர்க்கரேகையான 82°30' கிழக்கு தீர்க்கரேகை உத்தரப் பிரதேசத்தின் மிர்சாபூர் (அலகாபாத் அருகே) வழியாகச் செல்கிறது. இந்திய திட்ட நேரம் கிரீன்விச் சராசரி நேரத்தை (GMT) விட 5 மணி 30 நிமிடங்கள் முன்னதாக உள்ளது.","difficulty":"easy","topic":"இந்திய அமைவிடம்"},{"id":405,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மொத்த நிலப்பரப்பு மற்றும் உலகின் மொத்தப் பரப்பளவில் இந்தியாவின் பங்கு எவ்வளவு?","options":["32,87,263 ச.கி.மீ – 2.4%","31,87,263 ச.கி.மீ – 3.4%","34,87,263 ச.கி.மீ – 2.8%","30,87,263 ச.கி.மீ – 1.8%"],"correctAnswer":0,"explanation":"இந்தியாவின் மொத்த நிலப்பரப்பு 32,87,263 சதுர கிலோமீட்டர்கள் ஆகும். இது உலகின் மொத்தப் பரப்பளவில் 2.4 சதவீதமாகும்; பரப்பளவில் இந்தியா உலகின் ஏழாவது பெரிய நாடாகும்.","difficulty":"easy","topic":"இந்திய அமைவிடம்"},{"id":406,"subject":"gk","testNumber":5,"question":"இந்தியா தனது மிக நீளமான பன்னாட்டு நில எல்லையை எந்த நாட்டுடன் பகிர்ந்து கொள்கிறது?","options":["சீனா","பாகிஸ்தான்","நேபாளம்","வங்காளதேசம்"],"correctAnswer":3,"explanation":"இந்தியா மொத்தம் 15,200 கி.மீ நில எல்லையைக் கொண்டுள்ளது. இதில் மிக நீளமான எல்லையை வங்காளதேசத்துடன் (4,156 கி.மீ) பகிர்ந்து கொள்கிறது; மிகக் குறைந்த எல்லையை ஆப்கானிஸ்தானுடன் (106 கி.மீ) பகிர்ந்து கொள்கிறது.","difficulty":"easy","topic":"இந்திய அமைவிடம்"},{"id":407,"subject":"gk","testNumber":5,"question":"இந்தியாவின் வடக்கு–தெற்கு மற்றும் கிழக்கு–மேற்கு பரவல் நீளங்கள் முறையே எவ்வளவு?","options":["2,933 கி.மீ மற்றும் 3,214 கி.மீ","3,214 கி.மீ மற்றும் 2,933 கி.மீ","3,412 கி.மீ மற்றும் 2,833 கி.மீ","3,124 கி.மீ மற்றும் 2,933 கி.மீ"],"correctAnswer":1,"explanation":"இந்தியா வடக்கே காஷ்மீரில் உள்ள இந்திரா கோல் முதல் தெற்கே கன்னியாகுமரி வரை 3,214 கி.மீ நீளத்தையும், மேற்கே குஜராத்தின் ரான் ஆஃப் கட்ச் முதல் கிழக்கே அருணாச்சலப் பிரதேசம் வரை 2,933 கி.மீ அகலத்தையும் கொண்டுள்ளது.","difficulty":"medium","topic":"இந்திய அமைவிடம்"},{"id":408,"subject":"gk","testNumber":5,"question":"கீழ்க்கண்டவற்றுள் டிரான்ஸ் இமயமலை (திபெத்தியன் இமயமலை) பிரிவில் இடம்பெறும் மலைத்தொடர்கள் எவை?","options":["பீர்பாஞ்சால், தௌலதார், மகாபாரத்","காரோ, காசி, ஜெயந்தியா","சாஸ்கர், லடாக், கைலாஷ், காரகோரம்","விந்திய, சாத்பூரா, மைக்காலா"],"correctAnswer":2,"explanation":"டிரான்ஸ் இமயமலை அல்லது மேற்கு இமயமலை ஜம்மு-காஷ்மீர், லடாக் மற்றும் திபெத் பீடபூமியில் பரவியுள்ளது. சாஸ்கர், லடாக், கைலாஷ் மற்றும் காரகோரம் ஆகியவை இதன் முக்கிய மலைத்தொடர்கள் ஆகும்.","difficulty":"hard","topic":"இமயமலைப் பிரிவுகள்"},{"id":409,"subject":"gk","testNumber":5,"question":"இமயமலையின் பிரிவுகளில் எப்போதும் நிரந்தரப் பனி சூழ்ந்து காணப்படும் 'இமாத்ரி' (பெரிய இமயமலை) பகுதியில் அமைந்துள்ள இந்தியாவின் உயர்ந்த சிகரம் எது?","options":["நந்தா தேவி","கஞ்சன்ஜங்கா","குருசிகார்","தௌலகிரி"],"correctAnswer":1,"explanation":"இமாத்ரி எனப்படும் பெரிய இமயமலையின் சராசரி உயரம் 6,000 மீட்டர் ஆகும். உலகின் மிக உயர்ந்த எவரெஸ்ட் (8,848 மீ - நேபாளம்) மற்றும் சிக்கிம்-நேபாள எல்லையில் அமைந்துள்ள கஞ்சன்ஜங்கா (8,586 மீ) ஆகிய சிகரங்கள் இப்பிரிவில் உள்ளன.","difficulty":"medium","topic":"இமயமலைப் பிரிவுகள்"},{"id":410,"subject":"gk","testNumber":5,"question":"சிவாலிக் மலைத்தொடருக்கும் மத்திய இமயமலைக்கும் இடையே மேற்குப் பகுதியில் அமைந்துள்ள நீளமான பள்ளத்தாக்குகள் எவ்வாறு அழைக்கப்படுகின்றன?","options":["துவார்கள்","டூன்கள்","பாபர்கள்","கரேவாக்கள்"],"correctAnswer":1,"explanation":"சிவாலிக் (வெளி இமயமலை) மற்றும் இமாச்சல் மலைத்தொடர்களுக்கு இடையே காணப்படும் குறுகிய நீண்ட பள்ளத்தாக்குகள் மேற்கில் 'டூன்கள்' (எ.கா: டேராடூன்) எனவும், கிழக்கில் 'துவார்கள்' எனவும் அழைக்கப்படுகின்றன.","difficulty":"medium","topic":"இமயமலைப் பிரிவுகள்"},{"id":411,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மிக உயர்ந்த சிகரமான காட்வின் ஆஸ்டின் (K2 – 8,611 மீ) எந்த மலைத்தொடரில் அமைந்துள்ளது?","options":["காரகோரம் மலைத்தொடர்","பீர்பாஞ்சால் மலைத்தொடர்","சிவாலிக் மலைத்தொடர்","இமாச்சல் மலைத்தொடர்"],"correctAnswer":0,"explanation":"காட்வின் ஆஸ்டின் (K2) சிகரம் 8,611 மீட்டர் உயரத்துடன் காரகோரம் மலைத்தொடரில் அமைந்துள்ளது. இது இந்தியாவின் மிக உயர்ந்த சிகரமாகவும், எவரெஸ்டிற்கு அடுத்து உலகின் இரண்டாவது மிக உயர்ந்த சிகரமாகவும் திகழ்கிறது.","difficulty":"easy","topic":"இந்தியாவின் முக்கிய சிகரங்கள்"},{"id":412,"subject":"gk","testNumber":5,"question":"தென்னிந்தியாவின் மற்றும் மேற்குத் தொடர்ச்சி மலையின் மிக உயர்ந்த சிகரம் எது?","options":["தொட்டபெட்டா","மகேந்திரகிரி","ஆனைமுடி","குருசிகார்"],"correctAnswer":2,"explanation":"கேரளாவில் ஆனைமலை, ஏலக்காய் மலை மற்றும் பழனி மலைகள் சந்திக்கும் பகுதியில் அமைந்துள்ள ஆனைமுடி (2,695 மீ) தென்னிந்தியா மற்றும் மேற்குத் தொடர்ச்சி மலையின் மிக உயர்ந்த சிகரமாகும். தொட்டபெட்டா (2,637 மீ) இரண்டாவது உயர்ந்த சிகரமாகும்.","difficulty":"easy","topic":"இந்தியாவின் முக்கிய சிகரங்கள்"},{"id":413,"subject":"gk","testNumber":5,"question":"இமயமலையின் முக்கியக் கணவாய்களை அவை அமைந்துள்ள மாநிலங்கள்/பகுதிகளுடன் சரியாகப் பொருத்துக:\n(அ) நாதுலா – 1. இமாச்சலப் பிரதேசம்\n(ஆ) சிப்கிலா – 2. சிக்கிம்\n(இ) பொம்டிலா – 3. அருணாச்சலப் பிரதேசம்\n(ஈ) காரகோரம் – 4. லடாக் / ஜம்மு-காஷ்மீர்","options":["(அ)-2, (ஆ)-1, (இ)-3, (ஈ)-4","(அ)-1, (ஆ)-2, (இ)-4, (ஈ)-3","(அ)-2, (ஆ)-3, (இ)-1, (ஈ)-4","(அ)-4, (ஆ)-1, (இ)-3, (ஈ)-2"],"correctAnswer":0,"explanation":"நாதுலா மற்றும் ஜெலிப்லா கணவாய்கள் சிக்கிம் மாநிலத்திலும், சிப்கிலா கணவாய் இமாச்சலப் பிரதேசத்திலும், பொம்டிலா கணவாய் அருணாச்சலப் பிரதேசத்திலும், காரகோரம் கணவாய் லடாக்/ஜம்மு-காஷ்மீர் பகுதியிலும் அமைந்துள்ளன.","difficulty":"hard","topic":"இந்தியக் கணவாய்கள்"},{"id":414,"subject":"gk","testNumber":5,"question":"மேற்குத் தொடர்ச்சி மலையும் கிழக்குத் தொடர்ச்சி மலையும் ஒன்றாக இணையும் மலை எது?","options":["பழனி மலை","சேர்வராயன் மலை","ஜவ்வாது மலை","நீலகிரி மலை"],"correctAnswer":3,"explanation":"மேற்குத் தொடர்ச்சி மலை (சயாத்ரி) மற்றும் கிழக்குத் தொடர்ச்சி மலை (பூர்வாத்ரி) ஆகிய இரண்டும் தமிழ்நாடு, கேரளா மற்றும் கர்நாடகா எல்லைப்பகுதியில் உள்ள நீலகிரி மலையில் சந்திக்கின்றன.","difficulty":"easy","topic":"மேற்கு & கிழக்குத் தொடர்ச்சி மலைகள்"},{"id":415,"subject":"gk","testNumber":5,"question":"வட இந்தியச் சமவெளியில் ஆறுகளால் கொண்டு வரப்பட்டு ஒவ்வொரு ஆண்டும் படிய வைக்கப்படும் புதிய வண்டல் படிவுகள் எவ்வாறு அழைக்கப்படுகின்றன?","options":["பாங்கர்","பாபர்","காதர்","தராய்"],"correctAnswer":2,"explanation":"வட இந்தியப் பெரும் சமவெளியில் ஆறுகளால் படிய வைக்கப்படும் புதிய வண்டல் மண் 'காதர்' (அல்லது பெட் நிலம்) எனவும், பழைய வண்டல் படிவுகள் 'பாங்கர்' எனவும் அழைக்கப்படுகின்றன. காதர் மிகவும் வளமான வேளாண் நிலமாகும்.","difficulty":"medium","topic":"வட இந்திய சமவெளி"},{"id":416,"subject":"gk","testNumber":5,"question":"தக்காண பீடபூமி குறித்துக் கீழ்க்கண்டவற்றுள் சரியான கூற்று எது?","options":["இது வட்ட வடிவத்தில் அமைந்துள்ளது","இது முக்கோண வடிவில் அமைந்த தீபகற்ப இந்தியாவின் மிகப்பெரிய இயற்கைப் பிரிவாகும்","இது சுண்ணாம்புப் பாறைகளால் மட்டுமே உருவானது","இதன் வடக்கு எல்லையாகக் காவிரி ஆறு அமைந்துள்ளது"],"correctAnswer":1,"explanation":"தக்காண பீடபூமி தீபகற்ப இந்தியாவில் சுமார் 7 லட்சம் ச.கி.மீ பரப்பளவில் முக்கோண வடிவில் அமைந்துள்ளது. இதன் வடமேற்கில் விந்திய-சாத்பூரா மலைகளும், மேற்கில் மேற்குத் தொடர்ச்சி மலையும், கிழக்கில் கிழக்குத் தொடர்ச்சி மலையும் எல்லைகளாக உள்ளன.","difficulty":"medium","topic":"தக்காண பீடபூமி"},{"id":417,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மிகப் பழமையான மடிப்பு மலைத்தொடர் எது?","options":["இமயமலை","ஆரவல்லி மலைத்தொடர்","சாத்பூரா மலைத்தொடர்","மேற்குத் தொடர்ச்சி மலை"],"correctAnswer":1,"explanation":"ராஜஸ்தான் மாநிலத்தின் வழியே வடமேற்கிலிருந்து தென்மேற்காக நீண்டுள்ள ஆரவல்லி மலைத்தொடர் இந்தியாவின் மிகப் பழமையான மடிப்பு மலைத்தொடர் ஆகும். இதன் மிக உயர்ந்த சிகரம் குருசிகார் (1,722 மீ) ஆகும்.","difficulty":"easy","topic":"இந்திய இயற்கை அமைப்பு"},{"id":418,"subject":"gk","testNumber":5,"question":"தார் பாலைவனத்தில் பாய்ந்து கட்ச் வளைகுடா சதுப்புநிலத்தில் மறையும் முக்கிய உள்நாட்டு வடிகால் ஆறு எது?","options":["சபர்மதி","மாஹி","லூனி","சம்பல்"],"correctAnswer":2,"explanation":"ராஜஸ்தானின் ஆரவல்லி மலைத்தொடரில் உற்பத்தியாகும் லூனி ஆறு, தார் பாலைவனத்தின் வழியாகப் பாய்ந்து கடலை அடையாமல் குஜராத்தின் ரான் ஆஃப் கட்ச் பகுதியில் மறைந்துவிடும் முக்கிய உள்நாட்டு வடிகால் ஆறாகும்.","difficulty":"medium","topic":"தார் பாலைவனம்"},{"id":419,"subject":"gk","testNumber":5,"question":"அந்தமான் தீவுகளையும் நிக்கோபார் தீவுகளையும் பிரிக்கும் கடல் கால்வாய் எது?","options":["8° கால்வாய்","9° கால்வாய்","10° கால்வாய்","பாக் நீரிணை"],"correctAnswer":2,"explanation":"வங்காள விரிகுடாவில் அமைந்துள்ள அந்தமான் தீவுக் கூட்டத்தையும் நிக்கோபார் தீவுக் கூட்டத்தையும் 10° கால்வாய் பிரிக்கிறது. 8° கால்வாய் லட்சத்தீவின் மினிக்காய் தீவையும் மாலத்தீவையும் பிரிக்கிறது.","difficulty":"medium","topic":"இந்தியத் தீவுகள்"},{"id":420,"subject":"gk","testNumber":5,"question":"இந்தியாவின் ஒரே செயல்படும் எரிமலை (Active Volcano) எங்கு அமைந்துள்ளது?","options":["நார்க்கொண்டம் தீவு","கவரட்டி தீவு","பாம்பன் தீவு","பேரன் தீவு"],"correctAnswer":3,"explanation":"அந்தமான் நிக்கோபார் தீவுக்கூட்டத்தில் அமைந்துள்ள பேரன் தீவு (Barren Island) இந்தியாவின் ஒரே செயல்படும் எரிமலையாகும். நார்க்கொண்டம் தீவு உறங்கும் எரிமலையாகக் கருதப்படுகிறது.","difficulty":"easy","topic":"இந்தியத் தீவுகள்"},{"id":421,"subject":"gk","testNumber":5,"question":"அரபிக்கடலில் பவளப்பாறைகளால் உருவான லட்சத்தீவுகளின் நிர்வாகத் தலைநகரம் எது?","options":["போர்ட் பிளேர்","கவரட்டி","மினிக்காய்","அகத்தி"],"correctAnswer":1,"explanation":"அரபிக்கடலில் அமைந்துள்ள லட்சத்தீவுகள் பவளப்பாறைகளால் (Coral Islands) உருவானவை. இதன் நிர்வாகத் தலைநகரம் கவரட்டி ஆகும்; இத்தீவுக்கூட்டத்தில் உள்ள 'பிட் தீவு' பறவைகள் சரணாலயத்திற்குப் பெயர் பெற்றது.","difficulty":"easy","topic":"இந்தியத் தீவுகள்"},{"id":422,"subject":"gk","testNumber":5,"question":"தீவுக் கூட்டங்கள் உட்பட இந்தியாவின் மொத்த கடற்கரை நீளம் எவ்வளவு?","options":["6,100 கி.மீ","7,516.6 கி.மீ","5,422.6 கி.மீ","8,116.6 கி.மீ"],"correctAnswer":1,"explanation":"இந்திய முதன்மை நிலப்பரப்பின் கடற்கரை நீளம் 6,100 கி.மீ ஆகும். அந்தமான் நிக்கோபார் மற்றும் லட்சத்தீவுகளின் கடற்கரைகளையும் சேர்த்து இந்தியாவின் மொத்த கடற்கரை நீளம் 7,516.6 கி.மீ ஆகும்.","difficulty":"medium","topic":"இந்திய அமைவிடம்"},{"id":423,"subject":"gk","testNumber":5,"question":"சிந்து நதியின் மிகப்பெரிய துணையாறு எது?","options":["ஜீலம்","ராவி","பியாஸ்","செனாப்"],"correctAnswer":3,"explanation":"திபெத்தின் மானசரோவர் ஏரிக்கு அருகே உற்பத்தியாகும் சிந்து நதியின் முக்கியத் துணையாறுகள் ஜீலம், செனாப், ராவி, பியாஸ் மற்றும் சட்லஜ் ஆகும். இவற்றுள் செனாப் ஆறு சிந்து நதியின் மிகப்பெரிய துணையாறாகும்.","difficulty":"medium","topic":"இந்திய ஆறுகள்"},{"id":424,"subject":"gk","testNumber":5,"question":"கங்கை நதி வங்காளதேசத்திற்குள் நுழைந்ததும் எவ்வாறு அழைக்கப்படுகிறது?","options":["பத்மா","ஜமுனா","சாங்போ","ஹூக்ளி"],"correctAnswer":0,"explanation":"உத்தரகாண்டின் கங்கோத்ரி பனியாற்றில் பாகீரதியாக உற்பத்தியாகும் கங்கை (2,525 கி.மீ), வங்காளதேசத்திற்குள் நுழைந்ததும் 'பத்மா' என அழைக்கப்படுகிறது. பின்னர் பிரம்மபுத்திராவுடன் (ஜமுனா) இணைந்து 'மேக்னா' என்ற பெயரில் வங்காள விரிகுடாவில் கலக்கிறது.","difficulty":"easy","topic":"இந்திய ஆறுகள்"},{"id":425,"subject":"gk","testNumber":5,"question":"பிரம்மபுத்திரா ஆறு திபெத்தில் எவ்வாறு அழைக்கப்படுகிறது?","options":["திகாங்","ஜமுனா","சாங்போ","லோஹித்"],"correctAnswer":2,"explanation":"திபெத்தின் செமாயுங்டங் பனியாற்றில் உற்பத்தியாகும் பிரம்மபுத்திரா ஆறு திபெத்தில் 'சாங்போ' (தூய்மை என்பது பொருள்) எனவும், அருணாச்சலப் பிரதேசத்தில் 'திகாங்' எனவும், வங்காளதேசத்தில் 'ஜமுனா' எனவும் அழைக்கப்படுகிறது.","difficulty":"easy","topic":"இந்திய ஆறுகள்"},{"id":426,"subject":"gk","testNumber":5,"question":"தீபகற்ப இந்தியாவின் மிக நீளமான ஆறு மற்றும் 'விருத்த கங்கா' என அழைக்கப்படும் ஆறு எது?","options":["கிருஷ்ணா","கோதாவரி","மகாநதி","காவிரி"],"correctAnswer":1,"explanation":"மகாராஷ்டிராவின் நாசிக் மாவட்டத்தில் உள்ள திரியம்பகேஸ்வரில் உற்பத்தியாகும் கோதாவரி ஆறு 1,465 கி.மீ நீளத்துடன் தீபகற்ப இந்தியாவின் மிக நீளமான ஆறாக விளங்குகிறது. இது 'விருத்த கங்கா' என்றும் அழைக்கப்படுகிறது.","difficulty":"easy","topic":"இந்திய ஆறுகள்"},{"id":427,"subject":"gk","testNumber":5,"question":"மேற்கு நோக்கிப் பாய்ந்து அரபிக்கடலில் கழிமுகத்தை (Estuary) உருவாக்கும் இந்திய ஆறுகள் எவை?","options":["மகாநதி மற்றும் கோதாவரி","கிருஷ்ணா மற்றும் காவிரி","நர்மதை மற்றும் தபதி","கங்கை மற்றும் யமுனை"],"correctAnswer":2,"explanation":"மத்தியப் பிரதேசத்தின் அமர்கண்டக் பீடபூமியில் உற்பத்தியாகும் நர்மதை (1,312 கி.மீ) மற்றும் பெத்துல் மாவட்டத்தில் உற்பத்தியாகும் தபதி (724 கி.மீ) ஆகிய இரு ஆறுகளும் பிளவுப் பள்ளத்தாக்கின் வழியே மேற்கு நோக்கிப் பாய்ந்து அரபிக்கடலில் கழிமுகத்தை உருவாக்குகின்றன.","difficulty":"medium","topic":"இந்திய ஆறுகள்"},{"id":428,"subject":"gk","testNumber":5,"question":"கிருஷ்ணா ஆறு எந்த இடத்தில் உற்பத்தியாகிறது?","options":["மகாபலேஸ்வர்","அமர்கண்டக்","தலைக்காவிரி","சிஹாவா"],"correctAnswer":0,"explanation":"தீபகற்ப இந்தியாவின் இரண்டாவது மிக நீளமான ஆறான கிருஷ்ணா (1,400 கி.மீ), மகாராஷ்டிராவின் மேற்குத் தொடர்ச்சி மலையில் உள்ள மகாபலேஸ்வர் பகுதியில் உற்பத்தியாகிறது. துங்கபத்ரா, பீமா மற்றும் கொய்னா இதன் முக்கியத் துணையாறுகள் ஆகும்.","difficulty":"medium","topic":"இந்திய ஆறுகள்"},{"id":429,"subject":"gk","testNumber":5,"question":"காவிரி ஆறு கர்நாடக மாநிலத்தின் எந்த மலையில் உற்பத்தியாகிறது?","options":["நந்தி துர்க்கம்","பிரம்மகிரி குன்றுகள் (குடகு மலை)","மகாபலேஸ்வர்","வெள்ளியங்கிரி மலை"],"correctAnswer":1,"explanation":"காவிரி ஆறு கர்நாடக மாநிலத்தின் குடகு மலையில் உள்ள பிரம்மகிரி குன்றுகளில் 'தலைக்காவிரி' என்ற இடத்தில் உற்பத்தியாகிறது. சுமார் 800 கி.மீ நீளம் கொண்ட இது 'தென்னிந்தியாவின் கங்கை' என்றும் போற்றப்படுகிறது.","difficulty":"easy","topic":"இந்திய ஆறுகள்"},{"id":430,"subject":"gk","testNumber":5,"question":"இந்தியாவின் ஒட்டுமொத்த மழைப்பொழிவில் சுமார் 75 சதவீதத்தைத் தரும் பருவக்காற்று எது?","options":["வடகிழக்குப் பருவக்காற்று","மேற்கத்திய இடையூறுகள்","தென்மேற்குப் பருவக்காற்று","வணிகக் காற்று"],"correctAnswer":2,"explanation":"ஜூன் முதல் செப்டம்பர் வரை வீசும் தென்மேற்குப் பருவக்காற்று அரபிக்கடல் கிளை மற்றும் வங்காள விரிகுடா கிளை என இரண்டாகப் பிரிந்து இந்தியாவின் மொத்த மழைப்பொழிவில் சுமார் 75 சதவீதத்தைத் தருகிறது.","difficulty":"easy","topic":"இந்தியக் காலநிலை"},{"id":431,"subject":"gk","testNumber":5,"question":"உலகிலேயே மிக அதிக மழைப்பொழிவைப் பெறும் மௌசின்ராம் (1,141 செ.மீ) எந்த மாநிலத்தில் அமைந்துள்ளது?","options":["அசாம்","அருணாச்சலப் பிரதேசம்","சிக்கிம்","மேகாலயா"],"correctAnswer":3,"explanation":"மேகாலயா மாநிலத்தின் காசி குன்றுகளில் அமைந்துள்ள மௌசின்ராம் ஆண்டுக்குச் சராசரியாக 1,141 செ.மீ மழைப்பொழிவைப் பெற்று உலகிலேயே அதிக மழை பெறும் இடமாகத் திகழ்கிறது. புனல் வடிவ மலை அமைப்பு இதற்குக் காரணமாகும்.","difficulty":"easy","topic":"இந்தியக் காலநிலை"},{"id":432,"subject":"gk","testNumber":5,"question":"கோடைக்காலத்தில் கேரளா மற்றும் கர்நாடக கடற்கரைப் பகுதிகளில் மாங்காய்கள் விரைவில் முதிர்வதற்கு உதவும் இடியுடன் கூடிய மழை எவ்வாறு அழைக்கப்படுகிறது?","options":["கால்பைசாகி","லூ","மாஞ்சாரல்","நார்வெஸ்டர்"],"correctAnswer":2,"explanation":"ஏப்ரல்–மே மாதங்களில் கேரளா மற்றும் கர்நாடக கடற்கரைப் பகுதிகளில் பெய்யும் கோடை மழை மாங்காய்கள் விரைவில் முதிர்வதற்கு உதவுவதால் 'மாஞ்சாரல்' (Mango Showers) என அழைக்கப்படுகிறது. மேற்கு வங்காளத்தில் இது 'கால்பைசாகி' (நார்வெஸ்டர்) எனப்படுகிறது.","difficulty":"medium","topic":"இந்தியக் காலநிலை"},{"id":433,"subject":"gk","testNumber":5,"question":"இந்திய வேளாண் ஆராய்ச்சிக் கழகம் (ICAR) இந்தியாவில் உள்ள மண் வகைகளை எத்தனை பெரும் பிரிவுகளாக வகைப்படுத்தியுள்ளது?","options":["6 பிரிவுகள்","8 பிரிவுகள்","10 பிரிவுகள்","5 பிரிவுகள்"],"correctAnswer":1,"explanation":"1953-இல் இந்திய வேளாண் ஆராய்ச்சிக் கழகம் (ICAR) இந்திய மண் வகைகளை வண்டல் மண், கரிசல் மண், செம்மண், சரளை மண், காடு மற்றும் மலை மண், வறண்ட பாலைவன மண், உப்பு மற்றும் கார மண், களிமண் மற்றும் சதுப்புநில மண் என 8 பெரும் பிரிவுகளாக வகைப்படுத்தியுள்ளது.","difficulty":"medium","topic":"இந்திய மண் வகைகள்"},{"id":434,"subject":"gk","testNumber":5,"question":"'ரெகர் மண்' (Regur Soil) என்று அழைக்கப்படும், பருத்தி சாகுபடிக்கு மிகவும் ஏற்ற மண் வகை எது?","options":["வண்டல் மண்","செம்மண்","கரிசல் மண்","சரளை மண்"],"correctAnswer":2,"explanation":"தக்காண பீடபூமியில் எரிமலைப் பாறைகளான பசால்ட் பாறைகள் சிதைவடைவதால் உருவான கரிசல் மண் 'ரெகர் மண்' அல்லது 'பருத்தி மண்' என அழைக்கப்படுகிறது. இது ஈரப்பதத்தை நீண்ட காலம் தக்கவைக்கும் தன்மை கொண்டது.","difficulty":"easy","topic":"இந்திய மண் வகைகள்"},{"id":435,"subject":"gk","testNumber":5,"question":"இந்தியாவில் மிக அதிகப் பரப்பளவில் காணப்படும் மற்றும் வட இந்திய சமவெளிகளில் நெல், கோதுமை, கரும்பு சாகுபடிக்கு மிகவும் ஏற்ற மண் வகை எது?","options":["வண்டல் மண்","சரளை மண்","பாலைவன மண்","மலை மண்"],"correctAnswer":0,"explanation":"ஆறுகளால் அடித்து வரப்பட்டு படிய வைக்கப்படும் வண்டல் மண் இந்தியாவில் மிக அதிகப் பரப்பளவில் காணப்படும் மண் வகையாகும். இதில் பொட்டாசியம், பாஸ்பரிக் அமிலம் மற்றும் சுண்ணாம்புச் சத்துகள் நிறைந்துள்ளன.","difficulty":"easy","topic":"இந்திய மண் வகைகள்"},{"id":436,"subject":"gk","testNumber":5,"question":"அதிக வெப்பநிலை மற்றும் அதிக மழைப்பொழிவு கொண்ட பகுதிகளில் 'சுவருதல்' (Leaching) என்ற செயலால் உருவாகும் மண் வகை எது?","options":["கரிசல் மண்","வண்டல் மண்","செம்மண்","சரளை மண்"],"correctAnswer":3,"explanation":"அதிக வெப்பம் மற்றும் அதிக மழை பெய்யும் மேற்குத் தொடர்ச்சி மலை மற்றும் கிழக்குத் தொடர்ச்சி மலைப் பகுதிகளில் சுவருதல் (Leaching) செயலால் சரளை மண் (Laterite Soil) உருவாகிறது. இது காபி, தேயிலை, ரப்பர் மற்றும் முந்திரி பயிரிட ஏற்றது.","difficulty":"hard","topic":"இந்திய மண் வகைகள்"},{"id":437,"subject":"gk","testNumber":5,"question":"கீழ்க்கண்டவற்றுள் 'செம்மண்' சிவப்பு நிறத்தில் காணப்படுவதற்கான முக்கியக் காரணம் என்ன?","options":["அதிக மட்குச் சத்து இருப்பதால்","இரும்பு ஆக்சைடு அதிகமாக இருப்பதால்","கால்சியம் கார்பனேட் அதிகமாக இருப்பதால்","பொட்டாசியம் குறைவாக இருப்பதால்"],"correctAnswer":1,"explanation":"பழமையான படிகப் பாறைகளான கிரானைட் மற்றும் நைஸ் பாறைகள் சிதைவடைவதால் செம்மண் உருவாகிறது. இதில் இரும்பு ஆக்சைடு அதிக அளவில் நிறைந்துள்ளதால் இது சிவப்பு நிறத்தில் காணப்படுகிறது.","difficulty":"easy","topic":"இந்திய மண் வகைகள்"},{"id":438,"subject":"gk","testNumber":5,"question":"இந்தியாவின் வேளாண் பருவங்கள் மற்றும் அவற்றின் முக்கியப் பயிர்களைச் சரியாகப் பொருத்துக:\n(அ) காரீப் (ஜூன் – செப்டம்பர்) – 1. தர்பூசணி, வெள்ளரி\n(ஆ) ரபி (அக்டோபர் – மார்ச்) – 2. நெல், பருத்தி\n(இ) சையத் (ஏப்ரல் – ஜூன்) – 3. கோதுமை, கடுகு","options":["(அ)-2, (ஆ)-3, (இ)-1","(அ)-3, (ஆ)-2, (இ)-1","(அ)-2, (ஆ)-1, (இ)-3","(அ)-1, (ஆ)-3, (இ)-2"],"correctAnswer":0,"explanation":"காரீப் பருவம் தென்மேற்குப் பருவமழையுடன் தொடங்கி நெல், பருத்தி, மக்காச்சோளம் பயிரிடப்படுகிறது. ரபி பருவத்தில் (குளிர்காலம்) கோதுமை, பார்லி, கடுகு பயிரிடப்படுகிறது. சையத் (கோடைக்காலம்) பருவத்தில் தர்பூசணி, வெள்ளரி மற்றும் காய்கறிகள் பயிரிடப்படுகின்றன.","difficulty":"medium","topic":"இந்திய வேளாண்மை"},{"id":439,"subject":"gk","testNumber":5,"question":"கீழ்க்கண்டவற்றுள் 'ரபி' (Rabi) பருவப் பயிர் அல்லாதது எது?","options":["கோதுமை","பார்லி","கடுகு","மக்காச்சோளம்"],"correctAnswer":3,"explanation":"கோதுமை, பார்லி, கடுகு, கொண்டைக்கடலை மற்றும் ஆளி விதை ஆகியவை அக்டோபர் முதல் மார்ச் வரை பயிரிடப்படும் ரபி (குளிர்கால) பயிர்கள் ஆகும். மக்காச்சோளம் காரீப் பருவப் பயிராகும்.","difficulty":"medium","topic":"இந்திய வேளாண்மை"},{"id":440,"subject":"gk","testNumber":5,"question":"1936-ஆம் ஆண்டு உத்தரகாண்ட் மாநிலத்தில் நிறுவப்பட்ட இந்தியாவின் முதல் தேசியப் பூங்கா எது?","options":["காசிரங்கா தேசியப் பூங்கா","ஜிம் கார்பெட் தேசியப் பூங்கா","கிர் தேசியப் பூங்கா","கன்ஹா தேசியப் பூங்கா"],"correctAnswer":1,"explanation":"1936-ஆம் ஆண்டு 'ஹெய்லி தேசியப் பூங்கா' என்ற பெயரில் நிறுவப்பட்டுப் பின்னர் 'ஜிம் கார்பெட் தேசியப் பூங்கா' எனப் பெயரிடப்பட்ட உத்தரகாண்ட் பூங்காவே இந்தியாவின் முதல் தேசியப் பூங்காவாகும்.","difficulty":"easy","topic":"தேசியப் பூங்காக்கள் & உயிர்க்கோளக் காப்பகங்கள்"},{"id":441,"subject":"gk","testNumber":5,"question":"ஒற்றைக் கொம்பு காண்டாமிருகப் பாதுகாப்பிற்குப் புகழ்பெற்ற 'காசிரங்கா தேசியப் பூங்கா' எந்த மாநிலத்தில் அமைந்துள்ளது?","options":["மேற்கு வங்காளம்","மணிப்பூர்","அசாம்","ஜார்க்கண்ட்"],"correctAnswer":2,"explanation":"அசாம் மாநிலத்தில் பிரம்மபுத்திரா ஆற்றங்கரையில் அமைந்துள்ள காசிரங்கா தேசியப் பூங்கா உலகிலேயே அதிக எண்ணிக்கையிலான ஒற்றைக் கொம்பு காண்டாமிருகங்களைக் கொண்டுள்ளது. இது யுனெஸ்கோ உலகப் பாரம்பரியத் தலமாகும்.","difficulty":"easy","topic":"தேசியப் பூங்காக்கள் & உயிர்க்கோளக் காப்பகங்கள்"},{"id":442,"subject":"gk","testNumber":5,"question":"கங்கை–பிரம்மபுத்திரா டெல்டா பகுதியில் அமைந்துள்ள உலகின் மிகப்பெரிய சதுப்புநிலக் காடுகள் (மாங்குரோவ்) எவை?","options":["பிச்சாவரம் காடுகள்","பிதர்கனிகா காடுகள்","சுந்தரவனக் காடுகள்","கோரிங்கா காடுகள்"],"correctAnswer":2,"explanation":"மேற்கு வங்காளம் மற்றும் வங்காளதேசத்தில் கங்கை–பிரம்மபுத்திரா டெல்டாவில் அமைந்துள்ள சுந்தரவனக் காடுகள் உலகின் மிகப்பெரிய சதுப்புநிலக் காடுகளாகும். இங்கு 'சுந்தரி' என்ற மாங்குரோவ் மரங்களும் ராயல் வங்காளப் புலிகளும் காணப்படுகின்றன.","difficulty":"easy","topic":"இந்தியத் தாவரங்கள் & வனவிலங்குகள்"},{"id":443,"subject":"gk","testNumber":5,"question":"இந்தியாவின் முதல் உயிர்க்கோளக் காப்பகமாக 1986-ஆம் ஆண்டு அறிவிக்கப்பட்ட பகுதி எது?","options":["மன்னார் வளைகுடா","நந்தா தேவி","சுந்தரவனம்","நீலகிரி"],"correctAnswer":3,"explanation":"இந்தியாவில் மொத்தம் 18 உயிர்க்கோளக் காப்பகங்கள் உள்ளன. இவற்றுள் தமிழ்நாடு, கேரளா மற்றும் கர்நாடகா மாநிலங்களில் பரவியுள்ள நீலகிரி உயிர்க்கோளக் காப்பகம் 1986-இல் இந்தியாவின் முதல் உயிர்க்கோளக் காப்பகமாக அறிவிக்கப்பட்டது.","difficulty":"medium","topic":"தேசியப் பூங்காக்கள் & உயிர்க்கோளக் காப்பகங்கள்"},{"id":444,"subject":"gk","testNumber":5,"question":"இந்தியாவில் புலிகளைப் பாதுகாப்பதற்கான 'புலிகள் பாதுகாப்புத் திட்டம்' (Project Tiger) எப்போது தொடங்கப்பட்டது?","options":["1972","1973","1980","1992"],"correctAnswer":1,"explanation":"இந்திய வனவிலங்கு பாதுகாப்புச் சட்டம் 1972-இல் இயற்றப்பட்டது. அதனைத் தொடர்ந்து 1973-ஆம் ஆண்டு ஏப்ரல் மாதம் 'புலிகள் பாதுகாப்புத் திட்டம்' (Project Tiger) ஜிம் கார்பெட் தேசியப் பூங்காவில் தொடங்கப்பட்டது.","difficulty":"medium","topic":"இந்தியத் தாவரங்கள் & வனவிலங்குகள்"},{"id":445,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மிக உயரமான அணையான 'தெஹ்ரி அணை' (260.5 மீ) எந்த ஆற்றின் குறுக்கே கட்டப்பட்டுள்ளது?","options":["பாகீரதி ஆறு","சட்லஜ் ஆறு","மகாநதி","நர்மதை ஆறு"],"correctAnswer":0,"explanation":"உத்தரகாண்ட் மாநிலத்தில் பாகீரதி ஆற்றின் குறுக்கே கட்டப்பட்டுள்ள தெஹ்ரி அணை (260.5 மீ உயரம்) இந்தியாவின் மிக உயரமான அணையாகும். இது நீர்மின் உற்பத்தி மற்றும் நீர்ப்பாசனத்திற்குப் பயன்படுகிறது.","difficulty":"medium","topic":"இந்திய அணைகள்"},{"id":446,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மிக நீளமான அணையான 'ஹிராகுட் அணை' எந்த மாநிலத்தில், எந்த ஆற்றின் குறுக்கே அமைந்துள்ளது?","options":["பஞ்சாப் – சட்லஜ் ஆறு","ஒடிசா – மகாநதி","ஆந்திரப் பிரதேசம் – கிருஷ்ணா ஆறு","குஜராத் – நர்மதை ஆறு"],"correctAnswer":1,"explanation":"ஒடிசா மாநிலத்தில் மகாநதியின் குறுக்கே கட்டப்பட்டுள்ள ஹிராகுட் அணை (மொத்த நீளம் சுமார் 25.8 கி.மீ; முதன்மை அணை 4.8 கி.மீ) இந்தியாவின் மற்றும் உலகின் மிக நீளமான அணையாகும்.","difficulty":"easy","topic":"இந்திய அணைகள்"},{"id":447,"subject":"gk","testNumber":5,"question":"சட்லஜ் ஆற்றின் குறுக்கே கட்டப்பட்டுள்ள 'பக்ரா நங்கல் அணை' குறித்த சரியான கூற்று எது?","options":["இது உலகின் மிக உயரமான புவியீர்ப்பு அணைகளில் ஒன்றாகும்","இது கோதாவரி ஆற்றின் குறுக்கே கட்டப்பட்டுள்ளது","இதன் நீர்த்தேக்கம் ஸ்டான்லி நீர்த்தேக்கம் எனப்படுகிறது","இது மேற்கு வங்காள மாநிலத்தில் அமைந்துள்ளது"],"correctAnswer":0,"explanation":"இமாச்சலப் பிரதேசம்–பஞ்சாப் எல்லையில் சட்லஜ் ஆற்றின் குறுக்கே கட்டப்பட்டுள்ள பக்ரா நங்கல் அணை உலகின் மிக உயரமான புவியீர்ப்பு அணைகளில் ஒன்றாகும். இதன் நீர்த்தேக்கம் 'கோவிந்த் சாகர்' என அழைக்கப்படுகிறது.","difficulty":"medium","topic":"இந்திய அணைகள்"},{"id":448,"subject":"gk","testNumber":5,"question":"கீழ்க்கண்டவற்றுள் அதிக கார்பன் அளவு (80% முதல் 95% வரை) கொண்ட மிக உயர்தர நிலக்கரி வகை எது?","options":["பீட் (Peat)","லிக்னைட் (Lignite)","பிட்டுமினஸ் (Bituminous)","ஆந்த்ரசைட் (Anthracite)"],"correctAnswer":3,"explanation":"'கருப்புத் தங்கம்' எனப்படும் நிலக்கரி அதன் கார்பன் அளவைப் பொறுத்து ஆந்த்ரசைட் (80–95%), பிட்டுமினஸ் (60–80%), லிக்னைட் (40–60%) மற்றும் பீட் (40%-க்கும் குறைவு) என நான்கு வகைகளாகப் பிரிக்கப்படுகிறது.","difficulty":"medium","topic":"இந்திய கனிமங்கள்"},{"id":449,"subject":"gk","testNumber":5,"question":"அலுமினியம் பிரித்தெடுக்கப் பயன்படும் முக்கியத் தாது மற்றும் அதன் உற்பத்தியில் இந்தியாவில் முதலிடம் வகிக்கும் மாநிலம் எது?","options":["ஹேமடைட் – சத்தீஸ்கர்","பாக்சைட் – ஒடிசா","மைக்கா – ராஜஸ்தான்","மேக்னடைட் – கோவா"],"correctAnswer":1,"explanation":"பாக்சைட் என்பது நீரேற்றப்பட்ட அலுமினிய ஆக்சைடு கொண்ட அலுமினியத்தின் முக்கியத் தாதுவாகும். இந்தியாவின் பாக்சைட் இருப்பிலும் உற்பத்தியிலும் ஒடிசா மாநிலம் முதலிடம் வகிக்கிறது.","difficulty":"hard","topic":"இந்திய கனிமங்கள்"},{"id":450,"subject":"gk","testNumber":5,"question":"இந்தியாவின் முக்கியத் துறைமுகங்களை அவற்றின் சிறப்புத் தன்மையுடன் பொருத்துக:\n(அ) கண்ட்லா (தீன்தயாள்) – 1. ஆற்றுத் துறைமுகம்\n(ஆ) விசாகப்பட்டினம் – 2. ஓதத் துறைமுகம் (Tidal Port)\n(இ) கொல்கத்தா – 3. மிகப்பெரிய இயற்கைத் துறைமுகம்\n(ஈ) மும்பை – 4. ஆழமான நிலத்தால் சூழப்பட்ட துறைமுகம்","options":["(அ)-2, (ஆ)-4, (இ)-1, (ஈ)-3","(அ)-4, (ஆ)-2, (இ)-1, (ஈ)-3","(அ)-2, (ஆ)-1, (இ)-4, (ஈ)-3","(அ)-3, (ஆ)-4, (இ)-2, (ஈ)-1"],"correctAnswer":0,"explanation":"குஜராத்தின் கண்ட்லா (தீன்தயாள்) ஓதத் துறைமுகமாகவும், ஆந்திராவின் விசாகப்பட்டினம் மிக ஆழமான நிலத்தால் சூழப்பட்ட துறைமுகமாகவும், ஹூக்ளி ஆற்றங்கரையில் உள்ள கொல்கத்தா ஆற்றுத் துறைமுகமாகவும், மும்பை இந்தியாவின் மிகப்பெரிய இயற்கைத் துறைமுகமாகவும் விளங்குகின்றன.","difficulty":"hard","topic":"இந்தியப் போக்குவரத்து & துறைமுகங்கள்"},{"id":451,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் மொத்த நிலப்பரப்பு எவ்வளவு?","options":["1,30,058 ச.கி.மீ","1,40,058 ச.கி.மீ","1,20,058 ச.கி.மீ","1,35,058 ச.கி.மீ"],"correctAnswer":0,"explanation":"தமிழ்நாட்டின் மொத்த நிலப்பரப்பு 1,30,058 சதுர கிலோமீட்டர்கள் ஆகும். இது இந்தியாவின் மொத்த நிலப்பரப்பில் சுமார் 4 சதவீதத்தைக் கொண்டுள்ளது.","difficulty":"easy","topic":"தமிழ்நாடு அமைவிடம் & பரப்பளவு"},{"id":452,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் அட்ச மற்றும் தீர்க்கப் பரவல் முறையே எவ்வளவு?","options":["6°4' வ முதல் 12°35' வ வரை; 75°18' கி முதல் 81°20' கி வரை","8°4' வ முதல் 13°35' வ வரை; 76°18' கி முதல் 80°20' கி வரை","8°4' வ முதல் 15°35' வ வரை; 74°18' கி முதல் 80°20' கி வரை","9°4' வ முதல் 13°35' வ வரை; 76°18' கி முதல் 82°20' கி வரை"],"correctAnswer":1,"explanation":"தமிழ்நாடு 8°4' வடக்கு அட்சம் முதல் 13°35' வடக்கு அட்சம் வரையிலும், 76°18' கிழக்கு தீர்க்கம் முதல் 80°20' கிழக்கு தீர்க்கம் வரையிலும் இந்திய தீபகற்பத்தின் தென்கிழக்குப் பகுதியில் அமைந்துள்ளது.","difficulty":"hard","topic":"தமிழ்நாடு அமைவிடம் & பரப்பளவு"},{"id":453,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் கடற்கரை நீளம் எவ்வளவு மற்றும் இந்திய மாநிலங்களில் கடற்கரை நீளத்தில் தமிழ்நாட்டின் இடம் என்ன?","options":["976 கி.மீ – மூன்றாவது இடம்","1,276 கி.மீ – முதலிடம்","1,076 கி.மீ – மூன்றாவது இடம்","1,076 கி.மீ – இரண்டாவது இடம்"],"correctAnswer":3,"explanation":"தமிழ்நாடு 1,076 கி.மீ நீளமுள்ள கடற்கரையைக் கொண்டுள்ளது. இந்திய மாநிலங்களில் குஜராத்திற்கு அடுத்து இரண்டாவது மிக நீளமான கடற்கரையைக் கொண்ட மாநிலம் தமிழ்நாடு ஆகும்.","difficulty":"easy","topic":"தமிழ்நாடு அமைவிடம் & எல்லைகள்"},{"id":454,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் நான்கு திசை எல்லைக் கோடிகளைச் சரியாகப் பொருத்துக:\n(அ) கிழக்குக் கோடி – 1. ஆனைமலை\n(ஆ) மேற்குக் கோடி – 2. கோடியக்கரை\n(இ) வடக்குக் கோடி – 3. குமரி முனை\n(ஈ) தெற்குக் கோடி – 4. பழவேற்காடு ஏரி","options":["(அ)-2, (ஆ)-1, (இ)-4, (ஈ)-3","(அ)-1, (ஆ)-2, (இ)-4, (ஈ)-3","(அ)-2, (ஆ)-4, (இ)-1, (ஈ)-3","(அ)-4, (ஆ)-1, (இ)-2, (ஈ)-3"],"correctAnswer":0,"explanation":"தமிழ்நாட்டின் கிழக்குக் கோடியாகக் கோடியக்கரையும், மேற்குக் கோடியாக ஆனைமலையும், வடக்குக் கோடியாகப் பழவேற்காடு ஏரியும், தெற்குக் கோடியாகக் குமரி முனையும் அமைந்துள்ளன.","difficulty":"hard","topic":"தமிழ்நாடு அமைவிடம் & எல்லைகள்"},{"id":455,"subject":"gk","testNumber":5,"question":"நாகப்பட்டினம் மாவட்டத்திலிருந்து பிரிக்கப்பட்டு 2020-ஆம் ஆண்டு தமிழ்நாட்டின் 38-வது மாவட்டமாக உருவாக்கப்பட்ட மாவட்டம் எது?","options":["கள்ளக்குறிச்சி","தென்காசி","ராணிப்பேட்டை","மயிலாடுதுறை"],"correctAnswer":3,"explanation":"தமிழ்நாட்டில் தற்போது 38 மாவட்டங்கள் உள்ளன. நாகப்பட்டினம் மாவட்டத்திலிருந்து பிரிக்கப்பட்ட மயிலாடுதுறை மாவட்டம் 2020-ஆம் ஆண்டு தமிழ்நாட்டின் 38-வது மாவட்டமாக அதிகாரப்பூர்வமாக அறிவிக்கப்பட்டது.","difficulty":"easy","topic":"தமிழ்நாடு மாவட்டங்கள்"},{"id":456,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் முக்கிய நகரங்களின் சிறப்புப் பெயர்களைச் சரியாகப் பொருத்துக:\n(அ) கோயம்புத்தூர் – 1. தமிழ்நாட்டின் நெற்களஞ்சியம்\n(ஆ) தஞ்சாவூர் – 2. தென்னிந்தியாவின் மான்செஸ்டர்\n(இ) தூத்துக்குடி – 3. குட்டி ஜப்பான்\n(ஈ) சிவகாசி – 4. முத்து நகரம்","options":["(அ)-2, (ஆ)-1, (இ)-3, (ஈ)-4","(அ)-1, (ஆ)-2, (இ)-4, (ஈ)-3","(அ)-2, (ஆ)-1, (இ)-4, (ஈ)-3","(அ)-4, (ஆ)-1, (இ)-2, (ஈ)-3"],"correctAnswer":2,"explanation":"கோயம்புத்தூர் பருத்தி நெசவாலைகளால் 'தென்னிந்தியாவின் மான்செஸ்டர்' எனவும், தஞ்சாவூர் 'தமிழ்நாட்டின் நெற்களஞ்சியம்' எனவும், தூத்துக்குடி 'முத்து நகரம்' எனவும், சிவகாசி பட்டாசு மற்றும் அச்சுத் தொழிலால் 'குட்டி ஜப்பான்' எனவும் அழைக்கப்படுகின்றன.","difficulty":"medium","topic":"தமிழ்நாடு மாவட்டங்கள் & சிறப்புப் பெயர்கள்"},{"id":457,"subject":"gk","testNumber":5,"question":"கீழ்க்கண்ட சிறப்புப் பெயர் இணைகளில் தவறாகப் பொருத்தப்பட்டுள்ளது எது?","options":["ஈரோடு – மஞ்சள் நகரம்","சேலம் – மாங்கனி நகரம்","திருப்பூர் – பின்னலாடை நகரம்","வேலூர் – பட்டு நகரம்"],"correctAnswer":3,"explanation":"காஞ்சிபுரம் 'பட்டு நகரம்' மற்றும் 'ஆயிரம் கோவில்களின் நகரம்' என அழைக்கப்படுகிறது. வேலூர் 'கோட்டை நகரம்' என அழைக்கப்படுகிறது. மற்ற மூன்று இணைகளும் சரியானவை.","difficulty":"medium","topic":"தமிழ்நாடு மாவட்டங்கள் & சிறப்புப் பெயர்கள்"},{"id":458,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் மிக உயர்ந்த சிகரமான தொட்டபெட்டா (2,637 மீ) மற்றும் இரண்டாவது உயர்ந்த சிகரமான முக்குருத்தி (2,554 மீ) ஆகியவை எந்த மலையில் அமைந்துள்ளன?","options":["நீலகிரி மலை","பழனி மலை","ஆனைமலை","பொதிகை மலை"],"correctAnswer":0,"explanation":"மேற்குத் தொடர்ச்சி மலையின் முக்கியப் பகுதியான நீலகிரி மலையில் 2,000 மீட்டருக்கும் மேல் உயரம் கொண்ட 24 சிகரங்கள் உள்ளன. இவற்றுள் தொட்டபெட்டா (2,637 மீ) மற்றும் முக்குருத்தி (2,554 மீ) முக்கியமானவை.","difficulty":"easy","topic":"தமிழ்நாடு – மேற்குத் தொடர்ச்சி மலைகள்"},{"id":459,"subject":"gk","testNumber":5,"question":"'மலைகளின் இளவரசி' என அழைக்கப்படும் கொடைக்கானல் எந்த மலையில் அமைந்துள்ளது மற்றும் அம்மலையின் மிக உயர்ந்த சிகரம் எது?","options":["நீலகிரி மலை – தொட்டபெட்டா","பழனி மலை – வந்தராவ்","ஏலக்காய் மலை – அகத்தியர் சிகரம்","சேர்வராயன் மலை – சோலைக்கரடு"],"correctAnswer":1,"explanation":"திண்டுக்கல் மாவட்டத்தில் பரவியுள்ள பழனி மலை மேற்குத் தொடர்ச்சி மலையின் கிழக்குப் பகுதியாகும். இதன் மிக உயர்ந்த சிகரம் வந்தராவ் (2,533 மீ) ஆகும்; வேம்படி சோலை (2,505 மீ) இரண்டாவது உயர்ந்த சிகரமாகும். கொடைக்கானல் இம்மலையில் அமைந்துள்ளது.","difficulty":"medium","topic":"தமிழ்நாடு – மேற்குத் தொடர்ச்சி மலைகள்"},{"id":460,"subject":"gk","testNumber":5,"question":"தமிழ்நாடு–கேரளா எல்லைப் பகுதியில் அமைந்துள்ள ஆனைமலையில் காணப்படும் முக்கிய நீர்மின் நிலையம் எது?","options":["குந்தா நீர்மின் நிலையம்","பைக்காரா நீர்மின் நிலையம்","காடம்பாறை நீர்மின் நிலையம்","பாபநாசம் நீர்மின் நிலையம்"],"correctAnswer":2,"explanation":"பாலக்காட்டுக் கணவாய்க்குத் தெற்கே அமைந்துள்ள ஆனைமலையில் ஆனைமலை புலிகள் காப்பகம், ஆழியாறு மற்றும் திருமூர்த்தி அணைகள், வால்பாறை மலைவாழிடம் மற்றும் காடம்பாறை நீர்மின் நிலையம் ஆகியவை அமைந்துள்ளன.","difficulty":"hard","topic":"தமிழ்நாடு – மேற்குத் தொடர்ச்சி மலைகள்"},{"id":461,"subject":"gk","testNumber":5,"question":"தென்மேற்குத் தமிழ்நாட்டில் ஏலக்காய், மிளகு மற்றும் காபி ஆகிய நறுமணப் பயிர்கள் அதிகம் பயிரிடப்படும் 'ஏலமலை' எதனுடன் இணைகிறது?","options":["வடமேற்கில் ஆனைமலை மற்றும் வடகிழக்கில் பழனி மலையுடன்","வடக்கில் ஜவ்வாது மலையுடன்","கிழக்கில் கொல்லிமலையுடன்","வடமேற்கில் சேர்வராயன் மலையுடன்"],"correctAnswer":0,"explanation":"தென்மேற்குத் தமிழ்நாட்டில் அமைந்துள்ள ஏலமலை (ஏலக்காய் மலை) வடமேற்கில் ஆனைமலையுடனும், வடகிழக்கில் பழனி மலை மற்றும் ஆண்டிப்பட்டி–வருசநாடு குன்றுகளுடனும் இணைகிறது. இங்கு ஏலக்காய் அதிகம் விளைவதால் இப்பெயர் பெற்றது.","difficulty":"hard","topic":"தமிழ்நாடு – மேற்குத் தொடர்ச்சி மலைகள்"},{"id":462,"subject":"gk","testNumber":5,"question":"சிவஜோதி பர்வதம், அகத்தியர் மலை மற்றும் தெற்கு கைலாயம் எனப் பல்வேறு பெயர்களால் அழைக்கப்படும் மேற்குத் தொடர்ச்சி மலை எது?","options":["மகேந்திரகிரி மலை","வருசநாடு மலை","நீலகிரி மலை","பொதிகை மலை"],"correctAnswer":3,"explanation":"திருநெல்வேலி மற்றும் கன்னியாகுமரி மாவட்டங்களில் பரவியுள்ள பொதிகை மலை 'அகத்தியர் மலை', 'சிவஜோதி பர்வதம்' மற்றும் 'தெற்கு கைலாயம்' என அழைக்கப்படுகிறது. களக்காடு முண்டந்துறை புலிகள் காப்பகம் இப்பகுதியில் அமைந்துள்ளது.","difficulty":"medium","topic":"தமிழ்நாடு – மேற்குத் தொடர்ச்சி மலைகள்"},{"id":463,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டில் அமைந்துள்ள கிழக்குத் தொடர்ச்சி மலையின் மிக உயர்ந்த சிகரமான 'சோலைக்கரடு' (1,620 மீ) எந்த மலையில் உள்ளது?","options":["சேர்வராயன் மலை","ஜவ்வாது மலை","கொல்லிமலை","கல்வராயன் மலை"],"correctAnswer":0,"explanation":"சேலம் நகருக்கு அருகே அமைந்துள்ள சேர்வராயன் மலையில் உள்ள சோலைக்கரடு (1,620 மீ) கிழக்குத் தொடர்ச்சி மலையின் தமிழ்நாட்டுப் பகுதியின் மிக உயர்ந்த சிகரமாகும். 'ஏழைகளின் ஊட்டி' எனப்படும் ஏற்காடு இம்மலையில் உள்ளது.","difficulty":"medium","topic":"தமிழ்நாடு – கிழக்குத் தொடர்ச்சி மலைகள்"},{"id":464,"subject":"gk","testNumber":5,"question":"காவலூரில் உள்ள வைணு பாப்பு வானவியல் தொலைநோக்கி மையம் (1967) எந்தக் கிழக்குத் தொடர்ச்சி மலையில் அமைந்துள்ளது?","options":["பச்சைமலை","கல்வராயன் மலை","ஜவ்வாது மலை","சேர்வராயன் மலை"],"correctAnswer":2,"explanation":"திருவண்ணாமலை, திருப்பத்தூர் மற்றும் வேலூர் மாவட்டப் பகுதிகளில் பரவியுள்ள ஜவ்வாது மலையின் உயர்ந்த சிகரம் மேல்பட்டு (1,166 மீ) ஆகும். 1967-இல் தொடங்கப்பட்ட காவலூர் வானவியல் தொலைநோக்கி மையம் இம்மலையில் அமைந்துள்ளது.","difficulty":"medium","topic":"தமிழ்நாடு – கிழக்குத் தொடர்ச்சி மலைகள்"},{"id":465,"subject":"gk","testNumber":5,"question":"பழங்காலப் பழங்குடியினரான 'கரலர்' என்பவர்களின் பெயரால் அழைக்கப்படும் கிழக்குத் தொடர்ச்சி மலை எது?","options":["கொல்லிமலை","சேர்வராயன் மலை","பச்சைமலை","கல்வராயன் மலை"],"correctAnswer":3,"explanation":"கள்ளக்குறிச்சி, விழுப்புரம் மற்றும் சேலம் மாவட்டப் பகுதிகளில் பரவியுள்ள கல்வராயன் மலை, அப்பகுதியில் வாழ்ந்த 'கரலர்' பழங்குடியினரின் பெயரால் இப்பெயர் பெற்றது. இது சின்ன கல்வராயன் மற்றும் பெரிய கல்வராயன் என இரு பிரிவுகளைக் கொண்டது.","difficulty":"medium","topic":"தமிழ்நாடு – கிழக்குத் தொடர்ச்சி மலைகள்"},{"id":466,"subject":"gk","testNumber":5,"question":"நாமக்கல் மாவட்டத்தில் அமைந்துள்ள, அறப்பளீஸ்வரர் கோவில் மற்றும் ஆகாயகங்கை நீர்வீழ்ச்சி ஆகியவற்றைக் கொண்ட மலை எது?","options":["கொல்லிமலை","பச்சைமலை","ஜவ்வாது மலை","கல்வராயன் மலை"],"correctAnswer":0,"explanation":"நாமக்கல் மாவட்டத்தில் அமைந்துள்ள கொல்லிமலை கிழக்குத் தொடர்ச்சி மலையின் முக்கியப் பகுதியாகும். இம்மலையில் பசுமை மாறாக் காடுகள், 70 கொண்டை ஊசி வளைவுகள், அறப்பளீஸ்வரர் கோவில் மற்றும் ஆகாயகங்கை நீர்வீழ்ச்சி உள்ளன.","difficulty":"easy","topic":"தமிழ்நாடு – கிழக்குத் தொடர்ச்சி மலைகள்"},{"id":467,"subject":"gk","testNumber":5,"question":"திருச்சிராப்பள்ளி, பெரம்பலூர் மற்றும் சேலம் மாவட்டங்களில் பரவியுள்ள, பலாப்பழ விளைச்சலுக்குப் பெயர் பெற்ற கிழக்குத் தொடர்ச்சி மலை எது?","options":["ஜவ்வாது மலை","பச்சைமலை","கல்வராயன் மலை","மகேந்திரகிரி மலை"],"correctAnswer":1,"explanation":"திருச்சிராப்பள்ளி, பெரம்பலூர் மற்றும் சேலம் மாவட்டங்களில் பரவியுள்ள தாழ்வான குன்றுத்தொடர் பச்சைமலை ஆகும். மற்ற மலைகளை விடப் பசுமையாகக் காணப்படுவதால் 'பச்சைமலை' என அழைக்கப்படுகிறது; இங்கு பலாப்பழம் பிரபலமான விளைபொருளாகும்.","difficulty":"medium","topic":"தமிழ்நாடு – கிழக்குத் தொடர்ச்சி மலைகள்"},{"id":468,"subject":"gk","testNumber":5,"question":"காவிரி ஆறு தமிழ்நாட்டில் எந்த இடத்தில் நுழைகிறது மற்றும் திருச்சிராப்பள்ளிக்கு அருகே எவ்வாறு இரு கிளைகளாகப் பிரிகிறது?","options":["மேட்டூர் – காவிரி மற்றும் பவானி","கரூர் – காவிரி மற்றும் அமராவதி","ஒகேனக்கல் – கொள்ளிடம் மற்றும் காவிரி","பவானி – காவிரி மற்றும் வெண்ணாறு"],"correctAnswer":2,"explanation":"காவிரி ஆறு தருமபுரி மாவட்டத்தின் ஒகேனக்கல் பகுதியில் தமிழ்நாட்டிற்குள் நுழைகிறது. தமிழ்நாட்டில் 416 கி.மீ நீளம் பாயும் இது, திருச்சிராப்பள்ளிக்கு அருகே வடகிளையான கொள்ளிடம் மற்றும் தென்கிளையான காவிரி எனப் பிரிந்து ஸ்ரீரங்கம் தீவை உருவாக்குகிறது.","difficulty":"medium","topic":"தமிழ்நாடு ஆறுகள்"},{"id":469,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் ஒரே வற்றாத ஆறு (Perennial River) எது மற்றும் அதன் உற்பத்தி இடம் எது?","options":["காவிரி – குடகு மலை","வைகை – வருசநாடு குன்றுகள்","தென்பெண்ணை – நந்தி துர்க்கம்","தாமிரபரணி – பொதிகை மலை (அகத்தியர் மலை)"],"correctAnswer":3,"explanation":"அகத்தியர் மலை (பொதிகை மலை) சிகரத்தில் பாபநாசம் பகுதியில் உற்பத்தியாகும் தாமிரபரணி (பொருநை) தமிழ்நாட்டின் ஒரே வற்றாத ஆறாகும். தென்மேற்கு மற்றும் வடகிழக்கு ஆகிய இரு பருவமழைகளாலும் இது நீர் பெறுகிறது.","difficulty":"easy","topic":"தமிழ்நாடு ஆறுகள்"},{"id":470,"subject":"gk","testNumber":5,"question":"தேனி மாவட்டத்தின் வருசநாடு குன்றுகளின் கிழக்குச் சரிவில் உற்பத்தியாகி மதுரை, சிவகங்கை, ராமநாதபுரம் வழியே பாயும் ஆறு எது?","options":["வைகை ஆறு","தாமிரபரணி ஆறு","அமராவதி ஆறு","பாலாறு"],"correctAnswer":0,"explanation":"வைகை ஆறு தேனி மாவட்டத்தின் வருசநாடு குன்றுகளில் உற்பத்தியாகி 258 கி.மீ நீளத்திற்கு மதுரை, சிவகங்கை மற்றும் ராமநாதபுரம் மாவட்டங்கள் வழியே பாய்ந்து ராமநாதபுரம் பெரிய ஏரி மற்றும் பாக் நீரிணையில் கலக்கிறது.","difficulty":"easy","topic":"தமிழ்நாடு ஆறுகள்"},{"id":471,"subject":"gk","testNumber":5,"question":"கர்நாடகாவின் கோலார் மாவட்டத்தில் (நந்தி துர்க்கம்) உற்பத்தியாகி வேலூர், ராணிப்பேட்டை, காஞ்சிபுரம் மற்றும் செங்கல்பட்டு வழியாக வங்காள விரிகுடாவில் கலக்கும் ஆறு எது?","options":["தென்பெண்ணை","பாலாறு","பவானி","வெள்ளாறு"],"correctAnswer":1,"explanation":"பாலாறு கர்நாடகாவின் கோலார் மாவட்டத்தின் தலகவரா கிராமத்திற்கு அருகே உற்பத்தியாகி மொத்தம் 348 கி.மீ (தமிழ்நாட்டில் 222 கி.மீ) பாய்ந்து செங்கல்பட்டு மாவட்டம் கூவத்தூர் அருகே வங்காள விரிகுடாவில் கலக்கிறது. பொன்னி மற்றும் செய்யாறு இதன் முக்கியத் துணையாறுகள் ஆகும்.","difficulty":"medium","topic":"தமிழ்நாடு ஆறுகள்"},{"id":472,"subject":"gk","testNumber":5,"question":"தென்பெண்ணை (பொன்னையாறு) குறித்த கீழ்க்கண்ட கூற்றுகளில் தவறானது எது?","options":["இது கர்நாடகாவின் நந்தி துர்க்கம் மலையின் கிழக்குச் சரிவில் உற்பத்தியாகிறது","இது கிருஷ்ணகிரி மாவட்டத்தின் வழியே தமிழ்நாட்டில் நுழைகிறது","திருக்கோவிலூர் அணையருகே கெடிலம் மற்றும் பெண்ணையாறு என இரு கிளைகளாகப் பிரிகிறது","இது தூத்துக்குடி மாவட்டத்தின் புன்னக்காயல் அருகே மன்னார் வளைகுடாவில் கலக்கிறது"],"correctAnswer":3,"explanation":"தென்பெண்ணை ஆறு கடலூருக்கு அருகே வங்காள விரிகுடாவில் கலக்கிறது (புன்னக்காயல் அருகே மன்னார் வளைகுடாவில் கலப்பது தாமிரபரணி ஆறு). கிருஷ்ணகிரி மற்றும் சாத்தனூர் அணைகள் தென்பெண்ணை ஆற்றின் குறுக்கே கட்டப்பட்டுள்ளன.","difficulty":"hard","topic":"தமிழ்நாடு ஆறுகள்"},{"id":473,"subject":"gk","testNumber":5,"question":"காவிரியின் துணையாறுகளான பவானி மற்றும் நொய்யல் ஆறுகள் குறித்துச் சரியான இணை எது?","options":["பவானி – ஈரோடு கூடுதுறையில் காவிரியுடன் இணைகிறது; நொய்யல் – வெள்ளியங்கிரி மலையில் உற்பத்தியாகிறது","பவானி – கரூரில் காவிரியுடன் இணைகிறது; நொய்யல் – பழனி மலையில் உற்பத்தியாகிறது","பவானி – தருமபுரியில் காவிரியுடன் இணைகிறது; நொய்யல் – சேர்வராயன் மலையில் உற்பத்தியாகிறது","பவானி – திருச்சியில் காவிரியுடன் இணைகிறது; நொய்யல் – கொல்லிமலையில் உற்பத்தியாகிறது"],"correctAnswer":0,"explanation":"நீலகிரி மற்றும் கேரள அட்டப்பாடி பகுதியில் உற்பத்தியாகும் பவானி ஆறு ஈரோடு மாவட்டத்தின் பவானி கூடுதுறையில் காவிரியுடன் இணைகிறது. கோயம்புத்தூர் வெள்ளியங்கிரி மலையில் உற்பத்தியாகும் நொய்யல் ஆறு கரூர் மாவட்டம் நொய்யல் அருகே காவிரியுடன் கலக்கிறது.","difficulty":"hard","topic":"தமிழ்நாடு ஆறுகள்"},{"id":474,"subject":"gk","testNumber":5,"question":"'தென்னிந்தியாவின் ஸ்பா' என அழைக்கப்படும் குற்றாலம் நீர்வீழ்ச்சி எந்த ஆற்றில், எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["தாமிரபரணி – திருநெல்வேலி","வைகை – தேனி","சிற்றாறு – தென்காசி","கோதையாறு – கன்னியாகுமரி"],"correctAnswer":2,"explanation":"மருத்துவ குணம் கொண்ட மூலிகை நீர் பாய்வதால் 'தென்னிந்தியாவின் ஸ்பா' என அழைக்கப்படும் குற்றாலம் நீர்வீழ்ச்சி தென்காசி மாவட்டத்தில் சிற்றாற்றில் (தாமிரபரணியின் துணையாறு) அமைந்துள்ளது.","difficulty":"medium","topic":"தமிழ்நாடு நீர்வீழ்ச்சிகள்"},{"id":475,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் முக்கிய நீர்வீழ்ச்சிகளை அவை அமைந்துள்ள மாவட்டங்களுடன் பொருத்துக:\n(அ) ஒகேனக்கல் – 1. தேனி\n(ஆ) சுருளி – 2. தருமபுரி\n(இ) பைக்காரா – 3. கன்னியாகுமரி\n(ஈ) திருப்பரப்பு – 4. நீலகிரி","options":["(அ)-2, (ஆ)-1, (இ)-3, (ஈ)-4","(அ)-1, (ஆ)-2, (இ)-4, (ஈ)-3","(அ)-2, (ஆ)-4, (இ)-1, (ஈ)-3","(அ)-2, (ஆ)-1, (இ)-4, (ஈ)-3"],"correctAnswer":3,"explanation":"'தென்னிந்தியாவின் நயாகரா' எனப்படும் ஒகேனக்கல் நீர்வீழ்ச்சி தருமபுரி மாவட்டத்திலும் (காவிரி), சுருளி நீர்வீழ்ச்சி தேனி மாவட்டத்திலும், பைக்காரா நீலகிரி மாவட்டத்திலும், திருப்பரப்பு கன்னியாகுமரி மாவட்டத்திலும் அமைந்துள்ளன.","difficulty":"medium","topic":"தமிழ்நாடு நீர்வீழ்ச்சிகள்"},{"id":476,"subject":"gk","testNumber":5,"question":"தமிழ்நாடு தனது ஆண்டு மழைப்பொழிவில் மிக அதிக அளவை (சுமார் 48%) எந்தப் பருவமழையின் மூலம் பெறுகிறது?","options":["வடகிழக்குப் பருவமழை","தென்மேற்குப் பருவமழை","கோடைக்கால வெப்பச்சலன மழை","குளிர்கால மேற்கத்திய இடையூறு மழை"],"correctAnswer":0,"explanation":"மேற்குத் தொடர்ச்சி மலையின் மழைமறைவுப் பகுதியில் தமிழ்நாடு அமைந்துள்ளதால் தென்மேற்குப் பருவமழையில் குறைந்த மழையே கிடைக்கிறது. அக்டோபர் முதல் டிசம்பர் வரை வீசும் வடகிழக்குப் பருவமழை மூலம் தமிழ்நாடு சுமார் 48% மழைப்பொழிவைப் பெறுகிறது.","difficulty":"easy","topic":"தமிழ்நாடு காலநிலை"},{"id":477,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டில் மிக அதிக மழைப்பொழிவைப் பெறும் பகுதி மற்றும் இந்தியாவின் மூன்றாவது அதிக மழை பெறும் பகுதி எது?","options":["ஏற்காடு (சேலம்)","கொடைக்கானல் (திண்டுக்கல்)","சின்னக்கல்லார் (வால்பாறை, கோயம்புத்தூர்)","குற்றாலம் (தென்காசி)"],"correctAnswer":2,"explanation":"கோயம்புத்தூர் மாவட்டத்தின் வால்பாறைக்கு அருகே அமைந்துள்ள சின்னக்கல்லார் தமிழ்நாட்டின் மிக அதிக மழைப்பொழிவு பெறும் பகுதியாகும். இது இந்திய அளவில் மௌசின்ராம் மற்றும் சிரபுஞ்சிக்கு அடுத்த மூன்றாவது அதிக மழை பெறும் பகுதியாகக் கருதப்படுகிறது.","difficulty":"medium","topic":"தமிழ்நாடு காலநிலை"},{"id":478,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் மொத்த நிலப்பரப்பில் சுமார் மூன்றில் இரண்டு பங்கு பரப்பளவில் காணப்படும் முதன்மையான மண் வகை எது?","options":["வண்டல் மண்","கரிசல் மண்","சரளை மண்","செம்மண்"],"correctAnswer":3,"explanation":"தமிழ்நாட்டின் மொத்தப் பரப்பளவில் சுமார் மூன்றில் இரண்டு பங்கு செம்மண் பரவியுள்ளது. குறிப்பாகச் சிவகங்கை மற்றும் ராமநாதபுரம் போன்ற மத்திய மற்றும் தென் மாவட்டங்களில் செம்மண் மிக அதிகமாகக் காணப்படுகிறது.","difficulty":"easy","topic":"தமிழ்நாடு மண் வகைகள்"},{"id":479,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டில் நெல் சாகுபடி செய்யப்படும் மூன்று முக்கிய வேளாண் பருவங்கள் எவை?","options":["சொர்ணவாரி, சம்பா, நவரை","காரீப், சையத், பைசாகி","ஆடிப்பட்டம், தைப்பட்டம், மாசிப்பட்டம்","குறுவை, தாளடி, ரபி"],"correctAnswer":0,"explanation":"தமிழ்நாட்டில் சொர்ணவாரி (சித்திரைப்பட்டம்: ஏப்ரல்–மே), சம்பா (ஆடிப்பட்டம்: ஜூலை–ஆகஸ்ட்) மற்றும் நவரை (நவம்பர்–டிசம்பர்) ஆகிய மூன்று முக்கியப் பருவங்களில் நெல் சாகுபடி மேற்கொள்ளப்படுகிறது.","difficulty":"medium","topic":"தமிழ்நாடு வேளாண்மை"},{"id":480,"subject":"gk","testNumber":5,"question":"தமிழ்நாடு நெல் ஆராய்ச்சி நிறுவனம் (TRRI) 1985-ஆம் ஆண்டு எங்கு நிறுவப்பட்டது?","options":["கோயம்புத்தூர்","ஆடுதுறை (தஞ்சாவூர்)","மதுரை","திண்டிவனம்"],"correctAnswer":1,"explanation":"தமிழ்நாடு வேளாண்மைப் பல்கலைக்கழகத்தின் (கோயம்புத்தூர்) கீழ் செயல்படும் 'தமிழ்நாடு நெல் ஆராய்ச்சி நிறுவனம்' (Tamil Nadu Rice Research Institute – TRRI) தஞ்சாவூர் மாவட்டத்தின் ஆடுதுறையில் 1985-இல் நிறுவப்பட்டது.","difficulty":"medium","topic":"தமிழ்நாடு வேளாண்மை"},{"id":481,"subject":"gk","testNumber":5,"question":"'ஸ்டான்லி நீர்த்தேக்கம்' என அழைக்கப்படும் மேட்டூர் அணை எந்த மாவட்டத்தில், எந்த ஆற்றின் குறுக்கே அமைந்துள்ளது?","options":["ஈரோடு – பவானி ஆறு","தருமபுரி – தென்பெண்ணை ஆறு","கரூர் – அமராவதி ஆறு","சேலம் – காவிரி ஆறு"],"correctAnswer":3,"explanation":"சேலம் மாவட்டத்தில் காவிரி ஆற்றின் குறுக்கே 1934-ஆம் ஆண்டு கட்டி முடிக்கப்பட்ட மேட்டூர் அணை 'ஸ்டான்லி நீர்த்தேக்கம்' என அழைக்கப்படுகிறது. இது காவிரி டெல்டா மாவட்டங்களின் முக்கிய நீர்ப்பாசன ஆதாரமாகும்.","difficulty":"easy","topic":"தமிழ்நாடு அணைகள்"},{"id":482,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மிகப்பெரிய மண் அணைகளில் ஒன்றான 'பவானிசாகர் அணை' எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["ஈரோடு","கோயம்புத்தூர்","நீலகிரி","திருப்பூர்"],"correctAnswer":0,"explanation":"ஈரோடு மாவட்டத்தில் சத்தியமங்கலத்திற்கு அருகே பவானி ஆற்றின் குறுக்கே கட்டப்பட்டுள்ள பவானிசாகர் அணை (கீழ்பவானி அணை) இந்தியாவின் மிகப்பெரிய மண் அணைகளில் (Earthen Dam) ஒன்றாகும்.","difficulty":"medium","topic":"தமிழ்நாடு அணைகள்"},{"id":483,"subject":"gk","testNumber":5,"question":"1959-ஆம் ஆண்டு திறக்கப்பட்ட வைகை அணை எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["மதுரை","சிவகங்கை","தேனி","திண்டுக்கல்"],"correctAnswer":2,"explanation":"வைகை அணை தேனி மாவட்டத்தின் ஆண்டிப்பட்டிக்கு அருகே வைகை ஆற்றின் குறுக்கே கட்டப்பட்டு 1959 ஜனவரி 21 அன்று திறக்கப்பட்டது. இது தேனி, மதுரை, திண்டுக்கல், சிவகங்கை மற்றும் ராமநாதபுரம் மாவட்டங்களுக்குப் பயன்படுகிறது.","difficulty":"medium","topic":"தமிழ்நாடு அணைகள்"},{"id":484,"subject":"gk","testNumber":5,"question":"'காரையாறு அணை' என்றும் அழைக்கப்படும் பாபநாசம் அணை எந்த ஆற்றின் குறுக்கே கட்டப்பட்டுள்ளது?","options":["வைகை ஆறு","கோதையாறு","அமராவதி ஆறு","தாமிரபரணி ஆறு"],"correctAnswer":3,"explanation":"திருநெல்வேலி மாவட்டத்தில் மேற்குத் தொடர்ச்சி மலையின் பொதிகை மலை அடிவாரத்தில் தாமிரபரணி ஆற்றின் குறுக்கே பாபநாசம் அணை (காரையாறு அணை) கட்டப்பட்டுள்ளது. இது திருநெல்வேலி மற்றும் தூத்துக்குடி மாவட்டங்களின் பாசனத்திற்கு உதவுகிறது.","difficulty":"medium","topic":"தமிழ்நாடு அணைகள்"},{"id":485,"subject":"gk","testNumber":5,"question":"1895-ஆம் ஆண்டு ஆங்கிலேயப் பொறியாளர் கர்னல் ஜான் பென்னி குயிக் அவர்களால் கட்டப்பட்ட அணை எது?","options":["முல்லைப்பெரியாறு அணை","மேட்டூர் அணை","பேச்சிப்பாறை அணை","பரம்பிக்குளம் அணை"],"correctAnswer":0,"explanation":"கேரளாவின் இடுக்கி மாவட்டத்தில் பெரியாறு ஆற்றின் குறுக்கே 1895-இல் கர்னல் ஜான் பென்னி குயிக் அவர்களால் கட்டப்பட்ட முல்லைப்பெரியாறு அணை, தமிழ்நாட்டின் தென் மாவட்டங்களான தேனி, மதுரை, திண்டுக்கல், சிவகங்கை மற்றும் ராமநாதபுரத்திற்கு நீராதாரமாக விளங்குகிறது.","difficulty":"easy","topic":"தமிழ்நாடு அணைகள்"},{"id":486,"subject":"gk","testNumber":5,"question":"திருவண்ணாமலை மாவட்டத்தில் செங்கம் வட்டத்தில் தென்பெண்ணை ஆற்றின் குறுக்கே கட்டப்பட்டுள்ள முக்கிய அணை எது?","options":["கிருஷ்ணகிரி அணை","சாத்தனூர் அணை","வீராணம் ஏரி","அமராவதி அணை"],"correctAnswer":1,"explanation":"திருவண்ணாமலை மாவட்டத்தில் செங்கம் அருகே சென்னகேசவ மலைகளுக்கு இடையே தென்பெண்ணை ஆற்றின் குறுக்கே சாத்தனூர் அணை 1958-இல் கட்டப்பட்டது. திருவண்ணாமலை, கள்ளக்குறிச்சி மற்றும் விழுப்புரம் மாவட்டங்கள் இதனால் பயனடைகின்றன.","difficulty":"medium","topic":"தமிழ்நாடு அணைகள்"},{"id":487,"subject":"gk","testNumber":5,"question":"சுமார் 1,100 ஹெக்டேர் பரப்பளவில் அமைந்துள்ள உலகின் இரண்டாவது மிகப்பெரிய சதுப்புநிலக் காடான 'பிச்சாவரம் சதுப்புநிலக் காடுகள்' எந்த மாவட்டத்தில் உள்ளன?","options":["நாகப்பட்டினம்","தஞ்சாவூர்","ராமநாதபுரம்","கடலூர்"],"correctAnswer":3,"explanation":"கடலூர் மாவட்டத்தின் சிதம்பரத்திற்கு அருகே அமைந்துள்ள பிச்சாவரம் சதுப்புநிலக் காடுகள் சுமார் 1,100 ஹெக்டேர் பரப்பளவில் உலகின் இரண்டாவது மிகப்பெரிய சதுப்புநிலக் காடாகத் திகழ்கிறது. இங்கு அவிசீனியா மற்றும் ரைசோபோரா போன்ற அலையாத்தித் தாவரங்கள் உள்ளன.","difficulty":"easy","topic":"தமிழ்நாடு காடுகள் & சதுப்புநிலங்கள்"},{"id":488,"subject":"gk","testNumber":5,"question":"1940-ஆம் ஆண்டு நிறுவப்பட்ட தமிழ்நாட்டின் முதல் வனவிலங்கு சரணாலயம் எது?","options":["முதுமலை வனவிலங்கு சரணாலயம்","ஆனைமலை வனவிலங்கு சரணாலயம்","முண்டந்துறை வனவிலங்கு சரணாலயம்","கோடியக்கரை வனவிலங்கு சரணாலயம்"],"correctAnswer":0,"explanation":"நீலகிரி மாவட்டத்தில் 1940-ஆம் ஆண்டு நிறுவப்பட்ட முதுமலை வனவிலங்கு சரணாலயம் தமிழ்நாட்டின் முதல் வனவிலங்கு சரணாலயமாகும். தற்போது இது புலிகள் காப்பகமாகவும் தேசியப் பூங்காவாகவும் விளங்குகிறது.","difficulty":"hard","topic":"தமிழ்நாடு வனவிலங்கு சரணாலயங்கள்"},{"id":489,"subject":"gk","testNumber":5,"question":"இந்திரா காந்தி வனவிலங்கு சரணாலயம் மற்றும் ஆனைமலை புலிகள் காப்பகம் எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["நீலகிரி","தேனி","கோயம்புத்தூர்","திண்டுக்கல்"],"correctAnswer":2,"explanation":"கோயம்புத்தூர் மாவட்டத்தின் பொள்ளாச்சி மற்றும் வால்பாறைப் பகுதிகளில் ஆனைமலை புலிகள் காப்பகம் (இந்திரா காந்தி வனவிலங்கு சரணாலயம் மற்றும் தேசியப் பூங்கா) அமைந்துள்ளது. இது யானை, புலி, வரையாடு உள்ளிட்ட வனவிலங்குகளின் வாழ்விடமாகும்.","difficulty":"medium","topic":"தமிழ்நாடு வனவிலங்கு சரணாலயங்கள்"},{"id":490,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டில் புலிகள் பாதுகாப்புக்காக 1988-ஆம் ஆண்டு உருவாக்கப்பட்ட களக்காடு முண்டந்துறை புலிகள் காப்பகம் எந்த மாவட்டத்தில் உள்ளது?","options":["கன்னியாகுமரி","விருதுநகர்","தூத்துக்குடி","திருநெல்வேலி"],"correctAnswer":3,"explanation":"திருநெல்வேலி மாவட்டத்தில் மேற்குத் தொடர்ச்சி மலையின் பொதிகை மலைப் பகுதியில் அமைந்துள்ள களக்காடு முண்டந்துறை புலிகள் காப்பகம் 1988-இல் தமிழ்நாட்டின் முதல் புலிகள் காப்பகமாக அறிவிக்கப்பட்டது.","difficulty":"medium","topic":"தமிழ்நாடு வனவிலங்கு சரணாலயங்கள்"},{"id":491,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டில் அமைந்துள்ள ஐந்து தேசியப் பூங்காக்களுள் பெருநகர எல்லைக்குள் அமைந்துள்ள மிகச்சிறிய தேசியப் பூங்கா எது?","options":["கிண்டி தேசியப் பூங்கா","முக்குருத்தி தேசியப் பூங்கா","முதுமலை தேசியப் பூங்கா","மன்னார் வளைகுடா தேசியப் பூங்கா"],"correctAnswer":0,"explanation":"தமிழ்நாட்டில் கிண்டி, முதுமலை, முக்குருத்தி, இந்திரா காந்தி (ஆனைமலை) மற்றும் மன்னார் வளைகுடா ஆகிய 5 தேசியப் பூங்காக்கள் உள்ளன. இவற்றுள் சென்னையில் உள்ள கிண்டி தேசியப் பூங்கா (2.70 ச.கி.மீ) நகர எல்லைக்குள் அமைந்துள்ள இந்தியாவின் மிகச்சிறிய தேசியப் பூங்காக்களில் ஒன்றாகும்.","difficulty":"medium","topic":"தமிழ்நாடு தேசியப் பூங்காக்கள்"},{"id":492,"subject":"gk","testNumber":5,"question":"அழிவின் விளிம்பில் உள்ள 'கடல் பசு' (Dugong) பாதுகாக்கப்படும் 21 தீவுகளை உள்ளடக்கிய கடல்சார் தேசியப் பூங்கா எது?","options":["பழவேற்காடு கடல்சார் பூங்கா","மன்னார் வளைகுடா கடல்சார் தேசியப் பூங்கா","பிச்சாவரம் கடல்சார் பூங்கா","கோடியக்கரை கடல்சார் பூங்கா"],"correctAnswer":1,"explanation":"ராமநாதபுரம் மற்றும் தூத்துக்குடி கடற்கரைக்கு அப்பால் 21 பவளத் தீவுகளை உள்ளடக்கிய மன்னார் வளைகுடா கடல்சார் தேசியப் பூங்கா (1986) மற்றும் உயிர்க்கோளக் காப்பகம் கடல் பசு (Dugong) மற்றும் பவளப்பாறைகளின் பாதுகாப்பு மையமாகத் திகழ்கிறது.","difficulty":"medium","topic":"தமிழ்நாடு தேசியப் பூங்காக்கள்"},{"id":493,"subject":"gk","testNumber":5,"question":"இந்தியாவின் மிகப் பழமையான பறவைகள் சரணாலயமான வேடந்தாங்கல் பறவைகள் சரணாலயம் தற்போது எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["திருவள்ளூர்","விழுப்புரம்","செங்கல்பட்டு","கடலூர்"],"correctAnswer":2,"explanation":"இந்தியாவின் மிகப் பழமையான பறவைகள் சரணாலயங்களில் ஒன்றான வேடந்தாங்கல் பறவைகள் சரணாலயம் முன்பு காஞ்சிபுரம் மாவட்டத்தில் இருந்தது; மாவட்டப் பிரிவினைக்குப் பிறகு தற்போது செங்கல்பட்டு மாவட்டத்தில் அமைந்துள்ளது.","difficulty":"medium","topic":"தமிழ்நாடு பறவைகள் சரணாலயங்கள்"},{"id":494,"subject":"gk","testNumber":5,"question":"பூநாரைகள் (Flamingos) மற்றும் வெளிமான்களுக்குப் (Blackbuck) புகழ்பெற்ற கோடியக்கரை (பாயிண்ட் காலிமர்) வனவிலங்கு & பறவைகள் சரணாலயம் எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["ராமநாதபுரம்","திருவாரூர்","தூத்துக்குடி","நாகப்பட்டினம்"],"correctAnswer":3,"explanation":"நாகப்பட்டினம் மாவட்டத்தின் வேதாரண்யம் அருகே அமைந்துள்ள கோடியக்கரை (பாயிண்ட் காலிமர்) வனவிலங்கு மற்றும் பறவைகள் சரணாலயம் வலசை வரும் பூநாரைகள் (Flamingos) மற்றும் வெளிமான்களின் பாதுகாப்புத் தளமாக விளங்குகிறது.","difficulty":"medium","topic":"தமிழ்நாடு பறவைகள் சரணாலயங்கள்"},{"id":495,"subject":"gk","testNumber":5,"question":"ஆந்திரப் பிரதேசம்–தமிழ்நாடு எல்லையில் அமைந்துள்ள, இந்தியாவின் இரண்டாவது பெரிய உவர்நீர் ஏரி மற்றும் பறவைகள் சரணாலயம் எது?","options":["பழவேற்காடு ஏரி (புலிகாட் ஏரி)","கலிவேலி ஏரி","செம்பரம்பாக்கம் ஏரி","வீராணம் ஏரி"],"correctAnswer":0,"explanation":"திருவள்ளூர் மாவட்டம் மற்றும் ஆந்திராவின் திருப்பதி/நெல்லூர் மாவட்ட எல்லையில் அமைந்துள்ள பழவேற்காடு ஏரி (புலிகாட் ஏரி) ஒடிசாவின் சில்கா ஏரிக்கு அடுத்து இந்தியாவின் இரண்டாவது மிகப்பெரிய உவர்நீர் ஏரியும் முக்கியப் பறவைகள் சரணாலயமும் ஆகும்.","difficulty":"hard","topic":"தமிழ்நாடு பறவைகள் சரணாலயங்கள்"},{"id":496,"subject":"gk","testNumber":5,"question":"இந்தியாவிலேயே மிக அதிக அளவில் பழுப்பு நிலக்கரி (Lignite) வெட்டியெடுக்கப்படும் நெய்வேலி எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["விழுப்புரம்","அரியலூர்","கடலூர்","நாகப்பட்டினம்"],"correctAnswer":2,"explanation":"கடலூர் மாவட்டத்தில் அமைந்துள்ள நெய்வேலி பழுப்பு நிலக்கரி நிறுவனம் (NLC) இந்தியாவின் மிகப்பெரிய பழுப்பு நிலக்கரி சுரங்கத்தையும் அனல்மின் நிலையங்களையும் கொண்டுள்ளது. இந்தியாவின் பழுப்பு நிலக்கரி இருப்பில் தமிழ்நாடு பெரும்பங்கைக் கொண்டுள்ளது.","difficulty":"easy","topic":"தமிழ்நாடு கனிம வளங்கள்"},{"id":497,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டில் மேக்னசைட் (Magnesite) தாது மிக அதிக அளவில் கிடைக்கும் இடம் எது?","options":["திருநெல்வேலி","சேலம் (சாக்பீஸ் குன்றுகள்)","மதுரை (கரடிக்குட்டம்)","பெரம்பலூர்"],"correctAnswer":1,"explanation":"சேலம் மாவட்டத்தின் சாக்பீஸ் குன்றுகள் (Chalk Hills) பகுதியில் உயர்தர மேக்னசைட் தாது மிக அதிக அளவில் கிடைக்கிறது. மேலும் சேலத்தின் கஞ்சமலையில் இரும்புத் தாதுவும், மதுரையின் கரடிக்குட்டத்தில் மாலிப்டினமும் கிடைக்கின்றன.","difficulty":"hard","topic":"தமிழ்நாடு கனிம வளங்கள்"},{"id":498,"subject":"gk","testNumber":5,"question":"இந்தியாவின் முதல் பெருநிறுவனத் துறைமுகம் (Corporate Port) எது?","options":["சென்னைத் துறைமுகம்","தூத்துக்குடித் துறைமுகம்","விசாகப்பட்டினம் துறைமுகம்","எண்ணூர் (காமராஜர்) துறைமுகம்"],"correctAnswer":3,"explanation":"திருவள்ளூர் மாவட்டத்தில் சென்னைக்கு அருகே அமைந்துள்ள எண்ணூர் துறைமுகம் (காமராஜர் துறைமுகம்) 2001-இல் இந்தியாவின் முதல் பெருநிறுவனத் துறைமுகமாக (Corporate Port) உருவாக்கப்பட்டது. இது முதன்மையாக நிலக்கரி கையாளுதலுக்காக அமைக்கப்பட்டது.","difficulty":"hard","topic":"தமிழ்நாடு துறைமுகங்கள்"},{"id":499,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டில் உள்ள மூன்று பெரிய (Major) துறைமுகங்கள் எவை?","options":["சென்னை, எண்ணூர் (காமராஜர்), தூத்துக்குடி (வ.உ.சிதம்பரனார்)","சென்னை, நாகப்பட்டினம், கடலூர்","தூத்துக்குடி, ராமேஸ்வரம், குளச்சல்","சென்னை, எண்ணூர், நாகப்பட்டினம்"],"correctAnswer":0,"explanation":"தமிழ்நாட்டில் சென்னைத் துறைமுகம் (செயற்கைத் துறைமுகம்), எண்ணூர் (காமராஜர் துறைமுகம்) மற்றும் தூத்துக்குடி (வ.உ.சிதம்பரனார் துறைமுகம்) ஆகிய மூன்று பெரிய துறைமுகங்களும், நாகப்பட்டினம் என்ற ஒரு நடுத்தரத் துறைமுகமும் உள்ளன.","difficulty":"easy","topic":"தமிழ்நாடு துறைமுகங்கள்"},{"id":500,"subject":"gk","testNumber":5,"question":"தமிழ்நாட்டின் முக்கியத் தொழில் நகரங்களை அவற்றுக்குப் புகழ்பெற்ற தொழில்களுடன் சரியாகப் பொருத்துக:\n(அ) சென்னை – 1. தோல் பதனிடுதல்\n(ஆ) ஆம்பூர் & வாணியம்பாடி – 2. ஆசியாவின் டெட்ராய்ட் (வாகன உற்பத்தி)\n(இ) கரூர் – 3. எஃகு ஆலை (SAIL)\n(ஈ) சேலம் – 4. வீட்டு உபயோக ஜவுளி & பேருந்து கூண்டு கட்டுதல்","options":["(அ)-2, (ஆ)-1, (இ)-3, (ஈ)-4","(அ)-1, (ஆ)-2, (இ)-4, (ஈ)-3","(அ)-2, (ஆ)-4, (இ)-1, (ஈ)-3","(அ)-2, (ஆ)-1, (இ)-4, (ஈ)-3"],"correctAnswer":3,"explanation":"சென்னை வாகன உற்பத்தித் தொழிலால் 'ஆசியாவின் டெட்ராய்ட்' எனவும், ஆம்பூர் மற்றும் வாணியம்பாடி தோல் பதனிடுதலுக்கும், கரூர் வீட்டு உபயோக ஜவுளி மற்றும் பேருந்து கூண்டு கட்டுதலுக்கும், சேலம் இந்திய எஃகு ஆணையத்தின் (SAIL) துருப்பிடிக்காத எஃகு ஆலைக்கும் புகழ்பெற்றவை.","difficulty":"hard","topic":"தமிழ்நாடு தொழில் நகரங்கள்"}]);
